plan = params.get("plan") or {}
reported = params.get("reported") or []
if isinstance(reported, str):
    reported = [reported]
required_fields = [
    ("kickoffDate", "Kickoff date"),
    ("scopeVersion", "Scope version"),
    ("recipient", "Client contact"),
    ("invitation", "Kickoff invitation draft"),
    ("billingContact", "Billing contact"),
]
found = []
for field_key, field_label in required_fields:
    if not plan.get(field_key):
        found.append(field_label)
for note in reported:
    text = str(note).strip()
    if text and text not in found:
        found.append(text)
missing = found
ok = len(missing) == 0
